-- O-38 / O-139 (onprem/REGISTER.md) — Kostentraegerdatei Q4/2026 fuer die Box.
--
-- WAS: Stand der drei Kostentraeger-Tabellen nach dem SaaS-Lauf vom 01.10.2026
-- (`node tools/kostentraeger-annahmestellen-laden.mjs --write`, Stichtag
-- 2026-10-01 Berlin, ohne --stichtag). Quellen: AO05Q426_KE0, BK05Q426_KE0,
-- IK05Q426_KE0, EK05Q426_KE1 (gueltig ab 01.10.2026) + BN050526_KE0,
-- LK05Q226_KE0 (unveraendert gueltig).
--   kostentraeger                : 1043 Zeilen (datensatz_status = 'echt'),
--                                  davon 18 mit valid_to 2026-09-30
--                                  (17 IKK Nordrhein + 108916709 AOK Bayern
--                                  DLZ Schwandorf), 0 neue IK
--   kostentraeger_annahmestellen : 11411 Zeilen (SaaS-Lauf: +13 / ~5188 / -9)
--   kostentraeger_anschriften    : 1586 Zeilen  (SaaS-Lauf: +1 / ~1538 / -3)
-- Kern der Aenderung: AOK Bayern Papierannahmestelle (VKG 09, Code 67/68/71)
-- 108916709 -> 108910008 (Ebermannsdorf).
--
-- WARUM EINE NEUE DATEI: 0006/0007/0036/0037 sind angewandt und SHA-gesperrt
-- (README.md Kural 2). Sie bleiben unveraendert; diese Datei zieht die Box
-- vom Q2/Q3-Stand auf den Q4-Stand.
--
-- ⚠️ BEWUSSTE AUSNAHME VON "DELETE HIER NIE" (tools/seed-generieren.mjs Kopf):
--    Die Regel schuetzt `kostentraeger` — dort haengt ON DELETE CASCADE und die
--    prescriptions-FK. `kostentraeger` wird hier auch NICHT geloescht (nur
--    Upsert der fuenf Quartalsspalten, neue IK als volle Zeile).
--    Bei den beiden Untertabellen ist der DELETE dagegen der eigentliche Zweck:
--    eine veraltete VKG-Zeile ist eine falsche Annahmestelle (§302: Abweisung),
--    ein reiner Upsert wuerde die alte Adresse neben der neuen stehen lassen
--    und die Aufloesung mehrdeutig machen (genau Pruefung 71/72/20 unten).
--    Auf die Untertabellen zeigt keine FK (live geprueft 01.10.2026,
--    pg_constraint confrelid) — der DELETE reisst nichts mit.
--    Muster: Temp-Tabelle mit dem Soll-Stand -> Upsert -> DELETE alles, was
--    nicht im Soll steht. Alles in einer Transaktion (Kural 5) + DO-Selbstpruefung.
--
-- SaaS: NICHT angewandt (G7) — die Daten SIND der SaaS-Stand, aus dem die Datei
--    erzeugt wurde; ein Lauf dort waere ein No-op (gleiche Werte, 0 veraltete).
--
-- ERZEUGUNGSWEG (wie 0036/0037, DATABASE_URL ist im SaaS bewusst nicht gesetzt,
--    O-91): Zeilen ueber PostgREST gelesen, lokal im format('%L')-Format mit den
--    Spaltenlisten von tools/seed-generieren.mjs formatiert. Gleichheit BEWIESEN
--    (dieselbe format('%L')-Abfrage in der Live-DB, md5 ueber alle Zeilen):
--      kostentraeger                a473bfe4a7e890b57cc602d7b3b74eaa (lokal = Postgres)
--      kostentraeger_annahmestellen 9ced336a4d55c3de04d077b35cfc9791 (lokal = Postgres)
--      kostentraeger_anschriften    7cc535764fdd20d1f76fe6154eaf153b (lokal = Postgres)
--
-- ZAEHLER: counter-neutral (reine Daten-UPSERT/DELETE in bestehende public-
--          Tabellen; die Temp-Tabellen liegen in pg_temp und sind ON COMMIT DROP,
--          README.md Kural 6).

-- ─── 1) kostentraeger — kein DELETE, nur die fuenf Quartalsspalten ─────────────
CREATE TEMP TABLE _q4_kt (
  ik text, name text, das_ik text, payer_type text, region text, active boolean,
  valid_from date, valid_to date, updated_at timestamptz, kurzname text,
  abrechnender_kt_ik text, ist_abrechnender_kt boolean, quelle text,
  quelle_stand date, datensatz_status text
) ON COMMIT DROP;




-- Bestehende IK: nur valid_to / abrechnender_kt_ik / ist_abrechnender_kt /
-- quelle / quelle_stand. Neue IK (keine in Q4/2026, aber der Pfad bleibt
-- korrekt): die volle Zeile. Ein Statement -> FK abrechnender_kt_ik wird erst
-- am Statement-Ende geprueft.
SELECT ik, name, das_ik, payer_type, region, active, valid_from, valid_to, updated_at, kurzname, abrechnender_kt_ik, ist_abrechnender_kt, quelle, quelle_stand, datensatz_status FROM _q4_kt
ON CONFLICT (ik) DO UPDATE SET
  valid_to = EXCLUDED.valid_to,
  abrechnender_kt_ik = EXCLUDED.abrechnender_kt_ik,
  ist_abrechnender_kt = EXCLUDED.ist_abrechnender_kt,
  quelle = EXCLUDED.quelle,
  quelle_stand = EXCLUDED.quelle_stand;

-- ─── 2) kostentraeger_annahmestellen — Upsert + veraltete Zeilen weg ──────────
CREATE TEMP TABLE _q4_as (
  kostentraeger_ik text, verknuepfungsart text, partner_ik text,
  leistungserbringergruppe text, abrechnungscode text, art_datenlieferung text,
  uebermittlungsmedium text, bundesland text, quelle text, quelle_stand date
) ON COMMIT DROP;
























SELECT kostentraeger_ik, verknuepfungsart, partner_ik, leistungserbringergruppe, abrechnungscode, art_datenlieferung, uebermittlungsmedium, bundesland, quelle, quelle_stand FROM _q4_as
ON CONFLICT (kostentraeger_ik, verknuepfungsart, partner_ik, abrechnungscode, art_datenlieferung, uebermittlungsmedium, bundesland) DO UPDATE SET
  leistungserbringergruppe = EXCLUDED.leistungserbringergruppe,
  quelle = EXCLUDED.quelle,
  quelle_stand = EXCLUDED.quelle_stand;

DELETE FROM public.kostentraeger_annahmestellen t
WHERE NOT EXISTS (SELECT 1 FROM _q4_as s WHERE s.kostentraeger_ik = t.kostentraeger_ik AND s.verknuepfungsart = t.verknuepfungsart AND s.partner_ik = t.partner_ik AND s.abrechnungscode = t.abrechnungscode AND s.art_datenlieferung = t.art_datenlieferung AND s.uebermittlungsmedium = t.uebermittlungsmedium AND s.bundesland = t.bundesland);

-- ─── 3) kostentraeger_anschriften — Upsert + veraltete Zeilen weg ─────────────
CREATE TEMP TABLE _q4_an (
  kostentraeger_ik text, art text, plz text, ort text, strasse text,
  quelle text, quelle_stand date
) ON COMMIT DROP;





SELECT kostentraeger_ik, art, plz, ort, strasse, quelle, quelle_stand FROM _q4_an
ON CONFLICT (kostentraeger_ik, art, plz, ort, strasse) DO UPDATE SET
  quelle = EXCLUDED.quelle,
  quelle_stand = EXCLUDED.quelle_stand;

DELETE FROM public.kostentraeger_anschriften t
WHERE NOT EXISTS (SELECT 1 FROM _q4_an s WHERE s.kostentraeger_ik = t.kostentraeger_ik AND s.art = t.art AND s.plz = t.plz AND s.ort = t.ort AND s.strasse = t.strasse);

-- ─── 4) Selbstpruefung — schlaegt eine fehl, rollt die ganze Datei zurueck ────
DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM public.kostentraeger k JOIN _q4_kt s USING (ik)
   WHERE k.valid_to IS NOT DISTINCT FROM s.valid_to
     AND k.abrechnender_kt_ik IS NOT DISTINCT FROM s.abrechnender_kt_ik
     AND k.ist_abrechnender_kt IS NOT DISTINCT FROM s.ist_abrechnender_kt
     AND k.quelle IS NOT DISTINCT FROM s.quelle
     AND k.quelle_stand IS NOT DISTINCT FROM s.quelle_stand;
  IF n <> 1043 THEN RAISE EXCEPTION '0045: kostentraeger % statt 1043 Zeilen auf Q4-Stand', n; END IF;

  SELECT count(*) INTO n FROM public.kostentraeger_annahmestellen;
  IF n <> 11411 THEN RAISE EXCEPTION '0045: annahmestellen % statt 11411', n; END IF;

  SELECT count(*) INTO n FROM public.kostentraeger_anschriften;
  IF n <> 1586 THEN RAISE EXCEPTION '0045: anschriften % statt 1586', n; END IF;

  SELECT (SELECT count(*) FROM public.kostentraeger WHERE quelle = 'EK05Q226_KE0.txt')
       + (SELECT count(*) FROM public.kostentraeger_annahmestellen WHERE quelle = 'EK05Q226_KE0.txt')
       + (SELECT count(*) FROM public.kostentraeger_anschriften WHERE quelle = 'EK05Q226_KE0.txt') INTO n;
  IF n <> 0 THEN RAISE EXCEPTION '0045: noch % Zeilen mit quelle EK05Q226_KE0.txt', n; END IF;

  SELECT count(*) INTO n FROM public.kostentraeger_annahmestellen WHERE partner_ik = '108916709';
  IF n <> 0 THEN RAISE EXCEPTION '0045: noch % Zeilen mit partner_ik 108916709 (DLZ Schwandorf, bis 30.09.2026)', n; END IF;

  SELECT count(*) INTO n FROM (
    SELECT 1 FROM public.kostentraeger_annahmestellen
     WHERE abrechnungscode IN ('71', '72', '20') AND verknuepfungsart = '03'
     GROUP BY kostentraeger_ik, verknuepfungsart, abrechnungscode, art_datenlieferung, bundesland
    HAVING count(DISTINCT partner_ik) > 1) x;
  IF n <> 0 THEN RAISE EXCEPTION '0045: % mehrdeutige Annahmestellen (Code 71/72/20, VKG 03)', n; END IF;
END $$;
